using System.Drawing;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    private StatusStrip _statusStrip;

    public MyControl()
    {
        _statusStrip = new StatusStrip();

        // .NET 9: StatusStrip now defaults to ToolStripSystemRenderer.
        // Explicitly set the professional renderer to preserve .NET 8 appearance.
        _statusStrip.RenderMode = ToolStripRenderMode.ManagerRenderMode;
        ToolStripManager.Renderer = new ToolStripProfessionalRenderer();

        _statusStrip.Items.Add(new ToolStripStatusLabel("Ready"));
        Controls.Add(_statusStrip);
    }

    // .NET 9: DropDownControl now throws ArgumentNullException when passed null.
    // Always guard against null before calling.
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is not null)
        {
            editorService.DropDownControl(control);
        }
    }

    // .NET 9: Prefer LibraryImport over DllImport for better AOT support and
    // performance. Use nint instead of IntPtr for native interop handles.
    [LibraryImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static partial bool GetClientRect(nint hWnd, out RECT lpRect);

    [StructLayout(LayoutKind.Sequential)]
    private struct RECT
    {
        public int Left, Top, Right, Bottom;

        public readonly Size Size => new(Right - Left, Bottom - Top);
    }

    public Size GetNativeClientSize()
    {
        if (GetClientRect(Handle, out RECT rect))
            return rect.Size;
        return Size.Empty;
    }
}

